/* Replays the APDU transcripts generated by the Python reference (python/tests/gen_vectors.py).
 * The C kernel has to send byte-identical commands and reach the same outcome.
 *
 * usage: test_vectors <vector.txt>...
 */
#include "../src/opk_internal.h"

#include <stdio.h>
#include <stdlib.h>

#define MAX_APDUS 64

static int quiet; /* fuzz mode silences mismatch reports; sanitizer output still reaches stderr */
#define LOG(...) do { if (!quiet) fprintf(stderr, __VA_ARGS__); } while (0)

typedef struct {
    uint8_t c[MAX_APDUS][300];
    size_t cl[MAX_APDUS];
    uint8_t r[MAX_APDUS][300];
    size_t rl[MAX_APDUS];
    int n, pos, mismatch;
    char name[64];
} transcript;

typedef struct {
    char pins[4][13];
    int npins, next_pin;
    int online, approved;
    opk_online_response rsp;
    uint8_t scripts[512];
} host_state;

static size_t unhex(const char *s, uint8_t *out, size_t cap)
{
    size_t n = 0;
    while (s[0] && s[1] && n < cap && s[0] != ' ' && s[0] != '\n' && s[0] != ',') {
        unsigned v;
        sscanf(s, "%2x", &v);
        out[n++] = (uint8_t)v;
        s += 2;
    }
    return n;
}

static const char *field(const char *line, const char *key)
{
    static char buf[1200];
    char pat[40];
    snprintf(pat, sizeof pat, " %s=", key);
    const char *p = strstr(line, pat);
    if (!p)
        return NULL;
    p += strlen(pat);
    size_t n = 0;
    while (p[n] && p[n] != ' ' && p[n] != '\n' && n < sizeof buf - 1) {
        buf[n] = p[n];
        n++;
    }
    buf[n] = 0;
    return buf;
}

static int rng_state;
static void counter_rng(void *ctx, uint8_t *out, size_t n)
{
    (void)ctx;
    for (size_t i = 0; i < n; i++)
        out[i] = (uint8_t)(rng_state + i);
    rng_state = (int)((rng_state + n) & 0xFF);
}

static void hexdump(const char *p, const uint8_t *b, size_t n)
{
    LOG("%s", p);
    for (size_t i = 0; i < n; i++)
        LOG("%02X", b[i]);
    LOG("\n");
}

/* Fuzz mode (OPK_FUZZ=<iterations>): corrupt card responses and only check for crashes,
 * which ASan/UBSan then catch. Divergent commands are expected and ignored. */
static unsigned fuzz_seed;
static int fuzzing;
static unsigned fuzz_rand(void)
{
    fuzz_seed = fuzz_seed * 1103515245u + 12345u;
    return fuzz_seed >> 8;
}

static int replay(void *ctx, const uint8_t *c, size_t cl, uint8_t *r, size_t *rl)
{
    transcript *t = ctx;
    if (fuzzing) {
        int i = t->pos < t->n ? t->pos++ : (int)(fuzz_rand() % (unsigned)t->n);
        memcpy(r, t->r[i], t->rl[i]);
        *rl = t->rl[i];
        int flips = (int)(fuzz_rand() % 4);
        for (int k = 0; k < flips && *rl > 2; k++)
            r[fuzz_rand() % (*rl - 2)] ^= (uint8_t)(1u << (fuzz_rand() % 8));
        if (fuzz_rand() % 8 == 0 && *rl > 3) { /* truncate, keep SW */
            size_t cut = fuzz_rand() % (*rl - 2);
            memmove(r + cut, r + *rl - 2, 2);
            *rl = cut + 2;
        }
        return 0;
    }
    if (t->pos >= t->n) {
        LOG("[%s] unexpected extra command\n", t->name);
        hexdump("  sent: ", c, cl);
        t->mismatch = 1;
        r[0] = 0x6F; r[1] = 0x00;
        *rl = 2;
        return 0;
    }
    int i = t->pos++;
    if (cl != t->cl[i] || memcmp(c, t->c[i], cl)) {
        if (!t->mismatch) {
            LOG("[%s] command %d differs\n", t->name, i);
            hexdump("  expected: ", t->c[i], t->cl[i]);
            hexdump("  sent:     ", c, cl);
        }
        t->mismatch = 1;
    }
    memcpy(r, t->r[i], t->rl[i]);
    *rl = t->rl[i];
    return 0;
}

static int host_choose(void *ctx, const opk_app_candidate *c, int n)
{
    (void)ctx; (void)c; (void)n;
    return 0;
}

static int host_pin(void *ctx, int online, int tries, char *pin)
{
    host_state *h = ctx;
    (void)online; (void)tries;
    if (h->next_pin >= h->npins)
        return 0;
    strcpy(pin, h->pins[h->next_pin++]);
    return 1;
}

static int host_online(void *ctx, const opk_db *db, opk_online_response *rsp)
{
    host_state *h = ctx;
    (void)db;
    if (!h->online)
        return 0;
    *rsp = h->rsp;
    return 1;
}

static int run_file_quiet;
static int run_file(const char *path)
{
    static opk_env env;
    static transcript t;
    static opk_db db;
    host_state host;
    opk_transaction txn;
    char line[4096], mode[16] = "";
    int exp_status = -1, exp_cvm = -1, failures = 0;
    struct { uint32_t tag; uint8_t v[64]; size_t l; } exp_tags[16];
    int nexp = 0;

    FILE *f = fopen(path, "r");
    if (!f) {
        perror(path);
        return 1;
    }
    memset(&env, 0, sizeof env);
    memset(&t, 0, sizeof t);
    memset(&host, 0, sizeof host);
    opk_terminal_defaults(&env.terminal);
    opk_transaction_defaults(&txn, 0);
    env.rng = counter_rng;
    rng_state = 0x11;

    while (fgets(line, sizeof line, f)) {
        const char *v;
        if (!strncmp(line, "SCENARIO ", 9)) {
            sscanf(line + 9, "%63s", t.name);
        } else if (!strncmp(line, "MODE ", 5)) {
            sscanf(line + 5, "%15s", mode);
        } else if (!strncmp(line, "TERM", 4)) {
            env.terminal.terminal_type = (uint8_t)strtol(field(line, "type"), NULL, 16);
            unhex(field(line, "caps"), env.terminal.capabilities, 3);
            unhex(field(line, "addcaps"), env.terminal.additional_capabilities, 5);
            unhex(field(line, "country"), env.terminal.country_code, 2);
        } else if (!strncmp(line, "CAPK", 4)) {
            opk_capk k;
            memset(&k, 0, sizeof k);
            unhex(field(line, "rid"), k.rid, 5);
            k.index = (uint8_t)strtol(field(line, "index"), NULL, 16);
            k.exponent_len = (uint8_t)unhex(field(line, "exp"), k.exponent, 3);
            strncpy(k.expiry, field(line, "expiry"), 6);
            k.modulus_len = (uint16_t)unhex(field(line, "mod"), k.modulus, sizeof k.modulus);
            opk_env_add_capk(&env, &k);
        } else if (!strncmp(line, "AID", 3)) {
            opk_aid_config *a = &env.aids[env.aid_count++];
            uint8_t aid[16];
            size_t al = unhex(field(line, "aid"), aid, 16);
            opk_aid_defaults(a, aid, al);
            a->kernel_id = (uint32_t)atoi(field(line, "kernel"));
            a->partial_match = (uint8_t)atoi(field(line, "partial"));
            a->floor_limit = (uint32_t)atol(field(line, "floor"));
            unhex(field(line, "tac_default"), a->tac_default, 5);
            unhex(field(line, "tac_denial"), a->tac_denial, 5);
            unhex(field(line, "tac_online"), a->tac_online, 5);
            unhex(field(line, "ttq"), a->ttq, 4);
            a->default_ddol_len = (uint8_t)unhex(field(line, "ddol"), a->default_ddol, 32);
            unhex(field(line, "version"), a->app_version, 2);
            if ((v = field(line, "cl_limit"))) a->cl_transaction_limit = atol(v);
            if ((v = field(line, "cvm_limit"))) a->cvm_required_limit = atol(v);
            if ((v = field(line, "extra"))) {
                char buf[1200];
                strcpy(buf, v);
                for (char *tok = strtok(buf, ","); tok; tok = strtok(NULL, ",")) {
                    uint32_t tag = (uint32_t)strtoul(tok, NULL, 16);
                    uint8_t val[64];
                    size_t vl = unhex(strchr(tok, ':') + 1, val, sizeof val);
                    a->extra_len = (uint16_t)(a->extra_len + opk_tlv_encode(tag, val, vl, a->extra + a->extra_len));
                }
            }
        } else if (!strncmp(line, "TXN", 3)) {
            txn.amount = (uint32_t)atol(field(line, "amount"));
            txn.amount_other = (uint32_t)atol(field(line, "other"));
            txn.type = (uint8_t)strtol(field(line, "type"), NULL, 16);
            strncpy(txn.date, field(line, "date"), 6);
            strncpy(txn.time, field(line, "time"), 6);
            unhex(field(line, "currency"), txn.currency_code, 2);
            txn.sequence_counter = (uint32_t)atol(field(line, "seq"));
        } else if (!strncmp(line, "HOST", 4)) {
            v = field(line, "pins");
            if (strcmp(v, "-")) {
                char buf[64];
                strcpy(buf, v);
                for (char *tok = strtok(buf, ","); tok && host.npins < 4; tok = strtok(NULL, ","))
                    strcpy(host.pins[host.npins++], tok);
            }
            host.online = atoi(field(line, "online"));
            host.rsp.approved = (uint8_t)atoi(field(line, "approved"));
            if (strcmp((v = field(line, "arc")), "-"))
                unhex(v, host.rsp.arc, 2);
            if (strcmp((v = field(line, "iad")), "-"))
                host.rsp.issuer_auth_data_len = (uint8_t)unhex(v, host.rsp.issuer_auth_data, 16);
            if (strcmp((v = field(line, "scripts")), "-")) {
                host.rsp.scripts_len = unhex(v, host.scripts, sizeof host.scripts);
                host.rsp.scripts = host.scripts;
            }
        } else if (line[0] == 'C' && line[1] == ' ') {
            t.cl[t.n] = unhex(line + 2, t.c[t.n], 300);
        } else if (line[0] == 'R' && line[1] == ' ') {
            t.rl[t.n] = unhex(line + 2, t.r[t.n], 300);
            t.n++;
        } else if (!strncmp(line, "EXPECT_TAG", 10)) {
            char tag[16], val[300];
            sscanf(line + 11, "%15s %299s", tag, val);
            exp_tags[nexp].tag = (uint32_t)strtoul(tag, NULL, 16);
            exp_tags[nexp].l = unhex(val, exp_tags[nexp].v, 64);
            nexp++;
        } else if (!strncmp(line, "EXPECT", 6)) {
            exp_status = atoi(field(line, "status"));
            exp_cvm = atoi(field(line, "cvm"));
        }
    }
    fclose(f);

    opk_reader reader = {replay, &t};
    opk_outcome out;
    if (!strcmp(mode, "contact")) {
        opk_contact_host h = {host_choose, host_pin, host_online, &host};
        opk_contact_process(&env, &txn, &reader, &h, &out, &db);
    } else {
        opk_contactless_process(&env, &txn, &reader, &out, &db);
    }
    if (t.mismatch)
        failures++;
    if (t.pos != t.n) {
        LOG("[%s] only %d of %d APDUs exchanged\n", t.name, t.pos, t.n);
        failures++;
    }
    if ((int)out.status != exp_status || (int)out.cvm != exp_cvm) {
        LOG("[%s] outcome %s/cvm %d, expected status %d/cvm %d\n", t.name, opk_status_name(out.status),
                out.cvm, exp_status, exp_cvm);
        failures++;
    }
    for (int i = 0; i < nexp; i++) {
        size_t l;
        const uint8_t *val = opk_db_get(&db, exp_tags[i].tag, &l);
        if (!val || l != exp_tags[i].l || memcmp(val, exp_tags[i].v, l)) {
            LOG("[%s] tag %X mismatch\n", t.name, exp_tags[i].tag);
            hexdump("  expected: ", exp_tags[i].v, exp_tags[i].l);
            if (val)
                hexdump("  got:      ", val, l);
            failures++;
        }
    }
    if (!run_file_quiet)
        printf("%-32s %s\n", t.name, failures ? "FAIL" : "ok");
    return failures ? 1 : 0;
}

static int fuzz_file(const char *path, int iterations);

int main(int argc, char **argv)
{
    int failed = 0;
    const char *fz = getenv("OPK_FUZZ");
    if (fz) {
        for (int i = 1; i < argc; i++)
            fuzz_file(argv[i], atoi(fz));
        printf("fuzzed %d vectors x %s iterations without crashing\n", argc - 1, fz);
        return 0;
    }
    for (int i = 1; i < argc; i++)
        failed += run_file(argv[i]);
    printf("%d/%d vectors passed\n", argc - 1 - failed, argc - 1);
    return failed ? 1 : 0;
}

static int fuzz_file(const char *path, int iterations)
{
    fuzzing = 1;
    run_file_quiet = 1;
    quiet = 1;
    for (int i = 0; i < iterations; i++) {
        fuzz_seed = (unsigned)i * 2654435761u;
        run_file(path);
    }
    return 0;
}
